import { assert, describe, test, clearStore, newMockEvent } from "matchstick-as/assembly/index";
import { Address, BigInt, Bytes, ethereum } from "@graphprotocol/graph-ts";
import { handleUserOperationEvent } from "../src/mapping";
import { UserOperationEvent } from "../generated/EntryPoint/EntryPoint";

// Real transaction on Arc Testnet: 0x1c187c1b4213cec9a002df230feded4d622a0e65227da104e08939be6f453167
// sender (Mandate agent smart account): 0x96997341d3FD8e2fc17754992106453e3be1f883
// vendor (quickscale): 0x8327BC1B2017AaF5b686285e09664a4B21456a48, amount: 500000000000000 wei
const REAL_TX_INPUT =
  "";

function createEvent(): UserOperationEvent {
  let event = changetype<UserOperationEvent>(newMockEvent());
  event.parameters = [];
  event.parameters.push(
    new ethereum.EventParam(
      "userOpHash",
      ethereum.Value.fromFixedBytes(Bytes.fromHexString("0xc917bf82ae6eb0719f4af4d7e3528273a2f30af58486d4733c1cbc2181c038b3"))
    )
  );
  event.parameters.push(
    new ethereum.EventParam("sender", ethereum.Value.fromAddress(Address.fromString("0x96997341d3FD8e2fc17754992106453e3be1f883")))
  );
  event.parameters.push(
    new ethereum.EventParam("paymaster", ethereum.Value.fromAddress(Address.fromString("0xf9aC568eAd72A58D8A99c11Cf832438681a21902")))
  );
  event.parameters.push(new ethereum.EventParam("nonce", ethereum.Value.fromUnsignedBigInt(BigInt.fromI32(1))));
  event.parameters.push(new ethereum.EventParam("success", ethereum.Value.fromBoolean(true)));
  event.parameters.push(new ethereum.EventParam("actualGasCost", ethereum.Value.fromUnsignedBigInt(BigInt.fromI32(1))));
  event.parameters.push(new ethereum.EventParam("actualGasUsed", ethereum.Value.fromUnsignedBigInt(BigInt.fromI32(1))));
  event.transaction.input = Bytes.fromHexString(REAL_TX_INPUT);
  return event;
}

describe("handleUserOperationEvent", () => {
  test("decodes the real vendor + amount from the nested execute() calldata", () => {
    clearStore();
    let event = createEvent();
    handleUserOperationEvent(event);

    assert.entityCount("UserOperation", 1);
    assert.fieldEquals(
      "UserOperation",
      "0xc917bf82ae6eb0719f4af4d7e3528273a2f30af58486d4733c1cbc2181c038b3",
      "vendor",
      "0x8327bc1b2017aaf5b686285e09664a4b21456a48"
    );
    assert.fieldEquals(
      "UserOperation",
      "0xc917bf82ae6eb0719f4af4d7e3528273a2f30af58486d4733c1cbc2181c038b3",
      "amount",
      "500000000000000"
    );
  });
});
